class Solution:
    def findKthNumber(self, m, n, k):
        """
        :type m: int
        :type n: int
        :type k: int
        :rtype: int
        """
        def count(target, m, n):
            return sum(min(target//i, n) for i in range(1, m+1))

        left, right = 1, m*n
        while left <= right:
            mid = left + (right-left)//2
            if count(mid, m, n) >= k:
                right = mid-1
            else:
                left = mid+1
        return left

