class Solution:
    def searchMatrix(self, matrix, target):
        """
        :type matrix: List[List[int]]
        :type target: int
        :rtype: bool
        """
        if not matrix:
            return False

        m, n = len(matrix), len(matrix[0])
        left, right = 0, m * n
        while left < right:
            mid = left + (right - left) // 2
            if matrix[mid // n][mid % n] >= target:
                right = mid
            else:
                left = mid + 1

        return left < m * n and matrix[left // n][left % n] == target

